  if (windowLayoutHash !== storedWindowLayoutHash) {
    try {
      store.execute("semio.designApp.setWindowLayout", windowLayout);
    } catch (error) {
      console.error("[DesignApp] Failed to migrate layout:", error);
    }
  }

